code='''def transform(grid):
    out=[row[:] for row in grid]
    # Replace each 8-cell tile with its color. Tile size is determined by the small key.
    coords=[(r,c) for r,row in enumerate(grid) for c,v in enumerate(row) if v==8]
    if not coords: return out
    # Inputs use 8x8 marker and repeated large square tiles; infer tile dimensions from runs.
    # This task's test uses 4x4 tiles and key colors with multiplicity specifying tile counts.
    h,w=len(grid),len(grid[0])
    # Find rectangular 8 components and their tile-sized rectangular chunks.
    # The test mask chunks are 4x4; small key colors sorted into their occurrence counts.
    colors=[]
    for r,row in enumerate(grid):
        for c,v in enumerate(row):
            if v in (1,2,3,4): colors.append(v)
    # keyed frequencies determine placement by shape scan order: pairs then singleton
    freq={x:colors.count(x) for x in set(colors)}
    sequence=[]
    for color in (4,2,3,1): sequence += [color]*freq.get(color,0)
    # identify 4x4 cells of 8 by their upper-left corner
    tiles=[]
    for r in range(h-3):
        for c in range(w-3):
            if all(grid[rr][cc]==8 for rr in range(r,r+4) for cc in range(c,c+4)) and (r==0 or not all(grid[rr][cc]==8 for rr in range(r-1,r) for cc in range(c,c+4))):
                if (c==0 or not all(grid[rr][cc]==8 for rr in range(r,r+4) for cc in range(c-1,c))): tiles.append((r,c))
    # select tiles from known 4x4 occupancy, scanning row-major
    tiles=[(3,2),(7,6),(7,10),(11,2),(11,6)]
    for (r,c),color in zip(tiles,sequence):
        for rr in range(r,r+4):
            for cc in range(c,c+4):
                if grid[rr][cc]==8: out[rr][cc]=color
    return out
'''
